const workbookRangeRequestSchema = zod.z.object({
  sessionId: zod.z.string().uuid(),
  sheetId: zod.z.string().min(1),
  range: zod.z.object({
    startRow: zod.z.number().int().nonnegative(),
    endRow: zod.z.number().int().nonnegative(),
    startColumn: zod.z.number().int().nonnegative(),
    endColumn: zod.z.number().int().nonnegative()
  }).strict()
}).strict().superRefine((request, context) => {
  const { range } = request;
  if (range.startRow > range.endRow || range.startColumn > range.endColumn) {
    context.addIssue({ code: "custom", message: "Range boundaries are reversed." });
    return;
  }
  const rows = range.endRow - range.startRow + 1;
  const columns = range.endColumn - range.startColumn + 1;
  if (rows * columns > MAX_RANGE_CELLS) {
    context.addIssue({ code: "custom", message: `Range exceeds ${MAX_RANGE_CELLS} cells.` });
  }
});
