          {
            label: tm("menuRedo"),
            accelerator: "Shift+CmdOrCtrl+Z",
            click: () => sendMenuAction("redo")
          },
          { type: "separator" },
          { role: "cut", label: labels.cut },
          { role: "copy", label: labels.copy },
          { role: "paste", label: labels.paste },
          { type: "separator" },
          { role: "selectAll", label: labels.selectAll }
