    setUiLang(normalizeLang(process.env.GENOFFICE_LANG ?? electron.app.getLocale()));
    electron.app.setAccessibilitySupportEnabled(true);
    installApplicationMenu();
    startCaptureServer();
    return createSheetsWindow();
